public class CounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("initial instance count", 0, Counter.getInstanceCount());
            Counter a = new Counter();
            Counter b = new Counter();
            Counter c = new Counter();
            check("count after creating three instances", 3, Counter.getInstanceCount());
            check("first instance id", 1, a.getId());
            check("second instance id", 2, b.getId());
            check("third instance id", 3, c.getId());
            Counter.resetCount();
            check("count after resetCount()", 0, Counter.getInstanceCount());
            Counter d = new Counter();
            check("id restarts after reset", 1, d.getId());
            check("count after reset plus one new instance", 1, Counter.getInstanceCount());
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

