public class Counter {

    private static int instanceCount = 0;

    private final int id;

    public Counter() {
        instanceCount++;
        this.id = instanceCount;
    }

    public static int getInstanceCount() {
        return instanceCount;
    }

    public static void resetCount() {
        instanceCount = 0;
    }

    public int getId() {
        return id;
    }
}
